import { z } from 'zod';

/**
 * SNAPFIX diagnosis contract (v1).
 *
 * This schema is deliberately conservative: every field is bounded, every
 * identifier is generated by SNAPFIX, and every recommendation that could be
 * unsafe is classified separately from model prose. Unknown keys are stripped.
 */

export const DIAGNOSIS_SCHEMA_VERSION = '1.0.0';
export const DIAGNOSIS_PROMPT_VERSION = '2026-10-v1';

export const CATEGORIES = [
  'appliance',
  'plumbing',
  'electrical',
  'heating_cooling',
  'furniture',
  'walls_floors',
  'electronics',
  'other',
] as const;
export type Category = (typeof CATEGORIES)[number];

export const SAFETY_LEVELS = ['low', 'medium', 'high', 'critical'] as const;
export type SafetyLevel = (typeof SAFETY_LEVELS)[number];

export const WARNING_CODES = [
  'gas_leak',
  'carbon_monoxide',
  'fire_smoke',
  'electrical_hazard',
  'structural_hazard',
  'chemical_hazard',
  'pressure_system',
  'vehicle_safety',
  'high_voltage',
  'unsafe_instruction_removed',
  'professional_required',
  'uncertain_evidence',
  'photo_limitation',
  'demo_mode',
] as const;
export type WarningCode = (typeof WARNING_CODES)[number];

export const CONFIDENCE_LEVELS = ['low', 'medium', 'high'] as const;
export const DIFFICULTIES = ['easy', 'moderate', 'advanced', 'professional'] as const;
export const REPAIRABILITY_VERDICTS = [
  'diy',
  'diy_with_caution',
  'professional',
  'replace',
  'unknown',
] as const;
export const STEP_TYPES = ['check', 'question', 'professional'] as const;
export const PROVIDER_MODES = ['vision', 'text', 'demo'] as const;
export const ESTIMATE_STATUSES = ['available', 'unavailable'] as const;

const confidenceSchema = z.number().min(0).max(1);
const shortText = (max: number) => z.string().trim().min(1).max(max);

export const safetyWarningSchema = z.object({
  code: z.enum(WARNING_CODES),
  severity: z.enum(SAFETY_LEVELS),
  message: shortText(400),
  source: z.enum(['rule', 'model']),
});

export const observationSchema = z.object({
  id: z.string().min(1).max(64),
  description: shortText(400),
  source: z.enum(['image', 'text', 'context']),
  confidence: confidenceSchema,
});

export const possibleCauseSchema = z.object({
  id: z.string().min(1).max(64),
  title: shortText(160),
  explanation: shortText(1000),
  confidence: confidenceSchema,
  evidence: z.array(shortText(300)).max(6),
  verification_needed: z.boolean(),
});

export const nextStepSchema = z.object({
  id: z.string().min(1).max(64),
  title: shortText(160),
  description: shortText(1000),
  type: z.enum(STEP_TYPES),
  safe: z.boolean(),
});

export const repairStepSchema = z.object({
  id: z.string().min(1).max(64),
  title: shortText(160),
  instructions: shortText(2000),
  warning: safetyWarningSchema.nullable(),
  requires_professional: z.boolean(),
});

export const repairOptionSchema = z.object({
  id: z.string().min(1).max(64),
  title: shortText(160),
  summary: shortText(800),
  difficulty: z.enum(DIFFICULTIES),
  duration_minutes: z
    .object({
      min: z.number().int().min(1).max(2880),
      max: z.number().int().min(1).max(2880),
    })
    .refine((value) => value.min <= value.max, {
      message: 'duration_minutes.min must be <= max',
    }),
  tools: z.array(shortText(120)).max(20),
  materials: z.array(shortText(120)).max(20),
  steps: z.array(repairStepSchema).min(1).max(20),
  professional_only: z.boolean(),
});

export const estimateSchema = z
  .object({
    status: z.enum(ESTIMATE_STATUSES),
    currency: z.string().regex(/^[A-Z]{3}$/),
    minimum: z.number().min(0).max(1_000_000).nullable(),
    maximum: z.number().min(0).max(1_000_000).nullable(),
    includes_parts: z.boolean().nullable(),
    includes_labor: z.boolean().nullable(),
    assumptions: z.array(shortText(400)).max(10),
    confidence: z.enum(CONFIDENCE_LEVELS).nullable(),
    data_source: shortText(200).nullable(),
    last_verified_at: z.string().datetime({ offset: true }).nullable(),
    unavailable_reason: shortText(500).nullable(),
  })
  .superRefine((value, ctx) => {
    if (value.status === 'available') {
      if (value.minimum === null || value.maximum === null) {
        ctx.addIssue({
          code: 'custom',
          message: 'An available estimate requires minimum and maximum values',
          path: ['minimum'],
        });
      } else if (value.minimum > value.maximum) {
        ctx.addIssue({
          code: 'custom',
          message: 'Estimate minimum must not exceed maximum',
          path: ['minimum'],
        });
      }
      if (!value.data_source) {
        ctx.addIssue({
          code: 'custom',
          message: 'An available estimate requires a data source',
          path: ['data_source'],
        });
      }
    } else {
      if (value.minimum !== null || value.maximum !== null) {
        ctx.addIssue({
          code: 'custom',
          message: 'An unavailable estimate must not contain amounts',
          path: ['minimum'],
        });
      }
      if (!value.unavailable_reason) {
        ctx.addIssue({
          code: 'custom',
          message: 'Explain why the estimate is unavailable',
          path: ['unavailable_reason'],
        });
      }
    }
  });

export const followUpQuestionSchema = z.object({
  id: z.string().min(1).max(64),
  question: shortText(300),
  why: shortText(400),
});

const analysisShape = {
  item: z.object({
    category: z.enum(CATEGORIES),
    identified_type: shortText(120),
    brand: shortText(120).nullable(),
    model: shortText(120).nullable(),
  }),
  summary: z.object({
    headline: shortText(180),
    plain_language: shortText(1600),
    confidence: confidenceSchema,
    uncertainty: z.array(shortText(400)).min(1).max(8),
  }),
  observations: z.array(observationSchema).min(1).max(10),
  possible_causes: z.array(possibleCauseSchema).min(1).max(6),
  safety: z.object({
    risk_level: z.enum(SAFETY_LEVELS),
    professional_required: z.boolean(),
    stop_guidance: z.boolean(),
    warnings: z.array(safetyWarningSchema).max(10),
    escalation: shortText(600).nullable(),
  }),
  next_steps: z.array(nextStepSchema).min(1).max(8),
  repairability: z.object({
    verdict: z.enum(REPAIRABILITY_VERDICTS),
    rationale: shortText(800),
  }),
  repair_options: z.array(repairOptionSchema).max(3),
  estimate: estimateSchema,
  limitations: z.array(shortText(500)).min(1).max(10),
  follow_up_questions: z.array(followUpQuestionSchema).max(3),
  provider: z.object({
    name: shortText(80),
    model: shortText(120),
    mode: z.enum(PROVIDER_MODES),
    generated_at: z.string().datetime({ offset: true }),
    schema_version: z.literal(DIAGNOSIS_SCHEMA_VERSION),
    prompt_version: z.string().min(1).max(80),
  }),
};

export const analysisSchema = z.object(analysisShape).superRefine((value, ctx) => {
  if (value.safety.professional_required) {
    if (!['professional', 'replace'].includes(value.repairability.verdict)) {
      ctx.addIssue({
        code: 'custom',
        message: 'Professional-required diagnoses must not recommend DIY repair',
        path: ['repairability', 'verdict'],
      });
    }
    value.repair_options.forEach((option, index) => {
      if (!option.professional_only) {
        ctx.addIssue({
          code: 'custom',
          message: 'Repair options must be professional-only when escalation is required',
          path: ['repair_options', index, 'professional_only'],
        });
      }
      option.steps.forEach((step, stepIndex) => {
        if (!step.requires_professional) {
          ctx.addIssue({
            code: 'custom',
            message: 'Every step must require a professional when escalation is required',
            path: ['repair_options', index, 'steps', stepIndex, 'requires_professional'],
          });
        }
      });
    });
  }

  const ids = [
    ...value.observations.map((entry) => entry.id),
    ...value.possible_causes.map((entry) => entry.id),
    ...value.next_steps.map((entry) => entry.id),
    ...value.follow_up_questions.map((entry) => entry.id),
  ];
  if (new Set(ids).size !== ids.length) {
    ctx.addIssue({
      code: 'custom',
      message: 'Assessment identifiers must be unique',
      path: ['observations'],
    });
  }

  if (value.safety.risk_level === 'critical' && !value.safety.stop_guidance) {
    ctx.addIssue({
      code: 'custom',
      message: 'Critical risk requires stop guidance',
      path: ['safety', 'stop_guidance'],
    });
  }

  if (value.safety.professional_required && value.estimate.status === 'available') {
    // Estimates can still be useful, but must never be presented as a DIY budget
    // for a professional-only job. The assumptions must carry that distinction.
    if (value.estimate.assumptions.length === 0) {
      ctx.addIssue({
        code: 'custom',
        message: 'Professional estimate requires explicit assumptions',
        path: ['estimate', 'assumptions'],
      });
    }
  }
});

export type SafetyWarning = z.infer<typeof safetyWarningSchema>;
export type Observation = z.infer<typeof observationSchema>;
export type PossibleCause = z.infer<typeof possibleCauseSchema>;
export type NextStep = z.infer<typeof nextStepSchema>;
export type RepairStep = z.infer<typeof repairStepSchema>;
export type RepairOption = z.infer<typeof repairOptionSchema>;
export type Estimate = z.infer<typeof estimateSchema>;
export type FollowUpQuestion = z.infer<typeof followUpQuestionSchema>;
export type DiagnosisAnalysis = z.infer<typeof analysisSchema>;

/** Raw model output contract. Provider prose is never trusted without this parse. */
export const modelAssessmentSchema = z.object({
  item: analysisShape.item,
  summary: analysisShape.summary,
  observations: analysisShape.observations,
  possible_causes: analysisShape.possible_causes,
  safety: z.object({
    risk_level: z.enum(SAFETY_LEVELS),
    professional_required: z.boolean(),
    stop_guidance: z.boolean(),
    warnings: z.array(safetyWarningSchema).max(10),
    escalation: shortText(600).nullable(),
  }),
  next_steps: analysisShape.next_steps,
  repairability: analysisShape.repairability,
  repair_options: analysisShape.repair_options,
  limitations: analysisShape.limitations,
  follow_up_questions: analysisShape.follow_up_questions,
});
export type ModelAssessment = z.infer<typeof modelAssessmentSchema>;

export type SafeParseResult =
  { success: true; data: DiagnosisAnalysis } | { success: false; issues: string[] };

export function parseAnalysis(input: unknown): SafeParseResult {
  const result = analysisSchema.safeParse(input);
  if (result.success) return { success: true, data: result.data };
  return {
    success: false,
    issues: result.error.issues.map(
      (issue) => `${issue.path.join('.') || 'root'}: ${issue.message}`,
    ),
  };
}

export function extractJsonObject(raw: string): unknown {
  const trimmed = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```$/i, '');
  try {
    return JSON.parse(trimmed);
  } catch {
    const start = trimmed.indexOf('{');
    const end = trimmed.lastIndexOf('}');
    if (start >= 0 && end > start) {
      return JSON.parse(trimmed.slice(start, end + 1));
    }
    throw new Error('The AI response did not contain a JSON object');
  }
}

export const DEFAULT_CURRENCY = 'MAD';
